// One HTML-entity decode pass for brand-name HTML/SVG text. Named refs come from the
// WHATWG HTML named character references table (semicolon-required keys only). Unknown
// names stay as source text. Numeric refs outside Unicode become U+FFFD.
// Regenerated by: tsx scripts/generate-html-named-entities.ts --from <entities.json>
import html5NamedEntities from './html5-named-entities.json' with { type: 'json' }

export const HTML5_NAMED_ENTITY_SOURCE = 'https://html.spec.whatwg.org/entities.json'

const NAMED = new Map<string, string>(Object.entries(html5NamedEntities as Record<string, string>))

export const HTML5_NAMED_ENTITY_COUNT = NAMED.size

const ENTITY = /&(?:#x([\da-fA-F]+)|#(\d+)|([a-zA-Z][a-zA-Z\d]*));/g

function decodeCodePoint(value: number): string {
  const invalid =
    !Number.isFinite(value) ||
    value <= 0 ||
    value > 0x10ffff ||
    (value >= 0xd800 && value <= 0xdfff)
  return invalid ? '\uFFFD' : String.fromCodePoint(value)
}

function replacement(
  match: string,
  hex: string | undefined,
  dec: string | undefined,
  name: string | undefined
): string {
  if (hex !== undefined) return decodeCodePoint(Number.parseInt(hex, 16))
  if (dec !== undefined) return decodeCodePoint(Number.parseInt(dec, 10))
  if (name === undefined) return match
  return NAMED.get(name) ?? match
}

export function decodeHtmlEntities(source: string): string {
  return source.replace(ENTITY, replacement)
}
